/**
 * tracker.js  –  CleverTap Auto-Tracker
 * ─────────────────────────────────────────────────────────────────────────────
 * Drop this file on your server and include it on every page:
 *   <script src="/tracker.js"></script>
 *
 * OR use the inline version generated by the Integration Tool dashboard.
 *
 * Configuration is read from window.CT_TRACKER_CONFIG if defined before the
 * script loads, otherwise from the defaults below.
 *
 * Example pre-configuration:
 *   <script>
 *     window.CT_TRACKER_CONFIG = {
 *       accountId:  "YOUR_ACCOUNT_ID",
 *       passcode:   "YOUR_PASSCODE",
 *       backendUrl: "https://your-backend.com",
 *       trackedEvents: []   // empty = track everything
 *     };
 *   </script>
 *   <script src="/tracker.js"></script>
 */

(function (global) {
  'use strict';

  // ── Merge config ────────────────────────────────────────────────────────────
  var cfg = Object.assign(
    {
      accountId:     '',
      passcode:      '',
      backendUrl:    'http://localhost:4000',
      trackedEvents: [],   // Empty array means "track all"
      batchSize:     5,
      flushInterval: 5000, // ms between automatic flushes
      debug:         false,
    },
    global.CT_TRACKER_CONFIG || {}
  );

  if (!cfg.accountId || !cfg.passcode) {
    console.warn('[CT Tracker] accountId and passcode are required. Tracking disabled.');
    return;
  }

  // ── State ───────────────────────────────────────────────────────────────────
  var _queue    = [];
  var _identity = null;
  var _timer    = null;

  // ── Identity ────────────────────────────────────────────────────────────────
  try {
    _identity = localStorage.getItem('ct_identity');
  } catch (_) {}

  if (!_identity) {
    _identity = 'anon_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
    try { localStorage.setItem('ct_identity', _identity); } catch (_) {}
  }

  // ── Logging helper ──────────────────────────────────────────────────────────
  function log() {
    if (cfg.debug) {
      var args = Array.prototype.slice.call(arguments);
      args.unshift('[CT Tracker]');
      console.log.apply(console, args);
    }
  }

  // ── Core: track ─────────────────────────────────────────────────────────────
  /**
   * Queues an event for dispatch to the backend.
   * @param {string} eventName
   * @param {object} [properties]
   */
  function track(eventName, properties) {
    // Filter by whitelist if provided
    if (cfg.trackedEvents.length && cfg.trackedEvents.indexOf(eventName) === -1) {
      return;
    }

    var evt = {
      identity:  _identity,
      eventName: eventName,
      eventData: Object.assign(
        {
          page_url:   global.location.href,
          page_title: document.title,
          referrer:   document.referrer,
          timestamp:  new Date().toISOString(),
          screen_res: global.screen.width + 'x' + global.screen.height,
          language:   navigator.language,
        },
        properties || {}
      ),
    };

    _queue.push(evt);
    log('Queued:', eventName, evt.eventData);

    if (_queue.length >= cfg.batchSize) {
      flush();
    }
  }

  // ── Core: flush ─────────────────────────────────────────────────────────────
  function flush() {
    if (!_queue.length) return;
    var batch = _queue.splice(0);
    dispatch(batch);
  }

  // ── Core: dispatch ──────────────────────────────────────────────────────────
  function dispatch(batch) {
    var endpoint = cfg.backendUrl.replace(/\/$/, '') + '/api/send-batch';
    var payload  = JSON.stringify({
      accountId: cfg.accountId,
      passcode:  cfg.passcode,
      events:    batch,
    });

    // Prefer sendBeacon for reliability on page-unload
    if (navigator.sendBeacon) {
      var blob = new Blob([payload], { type: 'application/json' });
      var ok   = navigator.sendBeacon(endpoint, blob);
      log('Beacon dispatched:', ok, 'events:', batch.length);
      return;
    }

    // Fallback: XHR
    try {
      var xhr = new XMLHttpRequest();
      xhr.open('POST', endpoint, true);
      xhr.setRequestHeader('Content-Type', 'application/json');
      xhr.onload = function () { log('XHR response:', xhr.status); };
      xhr.onerror = function () { console.error('[CT Tracker] XHR error'); };
      xhr.send(payload);
    } catch (e) {
      console.error('[CT Tracker] dispatch error', e);
    }
  }

  // ── Auto-flush setup ────────────────────────────────────────────────────────
  _timer = setInterval(flush, cfg.flushInterval);

  if (global.addEventListener) {
    global.addEventListener('beforeunload', flush);
    global.addEventListener('pagehide',     flush);
    // SPA support: flush on hash / history changes
    global.addEventListener('popstate',     function () { track('Page Viewed'); });
  }

  // ── Built-in detections ─────────────────────────────────────────────────────

  // 1. Page View
  track('Page Viewed');

  // 2. Product View (URL heuristic)
  (function () {
    var href = global.location.href.toLowerCase();
    if (/\/product\/|\/item\/|\/p\/|\/detail\/|productid=|\/dp\//.test(href)) {
      var titleEl = document.querySelector('h1, .product-title, .product-name, [class*="product-title"]');
      var priceEl = document.querySelector('.price, [class*="price"], [itemprop="price"]');
      track('Product Viewed', {
        product_name:  titleEl ? titleEl.innerText.trim().slice(0, 200) : '',
        product_price: priceEl ? priceEl.innerText.trim().slice(0, 50) : '',
        product_url:   global.location.href,
      });
    }
  })();

  // 3. Category / Listing View
  (function () {
    var href = global.location.href.toLowerCase();
    if (/\/category\/|\/collection\/|\/c\/|\/catalog\/|\/shop\/|\/browse\//.test(href)) {
      var catEl = document.querySelector('h1, .category-name, .page-title');
      track('Category Viewed', {
        category_name: catEl ? catEl.innerText.trim().slice(0, 100) : '',
      });
    }
  })();

  // 4. Purchase confirmation
  (function () {
    var href = global.location.href.toLowerCase();
    if (/order-confirm|thank-you|order-success|checkout\/success|payment\/success/.test(href)) {
      var orderEl = document.querySelector('.order-id, [class*="order-number"], [class*="order-id"]');
      track('Purchase Completed', {
        order_id: orderEl ? orderEl.innerText.trim() : '',
      });
    }
  })();

  // 5. Delegate click listener
  var CLICK_RULES = [
    { selectors: ['.add-to-cart','[class*="add-to-cart"]','[data-action="add-to-cart"]','button[class*="addtocart"]','button[name="add"]','[class*="add_to_cart"]'], event: 'Added to Cart' },
    { selectors: ['.buy-now','[class*="buy-now"]','[class*="buynow"]','button[id*="buy"]'],                                                                           event: 'Buy Now Clicked' },
    { selectors: ['.checkout','[class*="checkout"]','a[href*="checkout"]','button[id*="checkout"]'],                                                                   event: 'Checkout Started' },
    { selectors: ['.add-to-wishlist','[class*="wishlist"]','[data-action="wishlist"]'],                                                                                event: 'Added to Wishlist' },
    { selectors: ['[class*="share"]','[data-action="share"]'],                                                                                                        event: 'Content Shared' },
  ];

  function matchesAny(el, selectors) {
    return selectors.some(function (s) {
      try { return el.matches(s); } catch (_) { return false; }
    });
  }

  document.addEventListener('click', function (e) {
    var el = e.target;
    for (var depth = 0; depth < 4 && el && el !== document; depth++) {
      for (var r = 0; r < CLICK_RULES.length; r++) {
        if (matchesAny(el, CLICK_RULES[r].selectors)) {
          track(CLICK_RULES[r].event, {
            element_text: (el.innerText || el.textContent || '').trim().slice(0, 100),
            element_tag:  el.tagName.toLowerCase(),
            element_id:   el.id || '',
            element_class: el.className || '',
          });
          return;
        }
      }
      el = el.parentElement;
    }
  }, true);

  // 6. Form submit listener
  document.addEventListener('submit', function (e) {
    var form   = e.target;
    var clues  = [form.action, form.id, form.className].join(' ').toLowerCase();

    var eventName;
    if (/login|signin|sign-in/.test(clues))  eventName = 'User Login';
    else if (/signup|register|join/.test(clues)) eventName = 'User Signup';
    else if (/checkout|payment/.test(clues)) eventName = 'Checkout Started';
    else if (/search/.test(clues))           eventName = 'Search Performed';
    else if (/newsletter|subscribe/.test(clues)) eventName = 'Newsletter Subscribed';
    else if (/contact|enquiry/.test(clues))  eventName = 'Contact Form Submitted';
    else                                     eventName = 'Form Submitted';

    var searchInput = form.querySelector('[name="q"],[name="query"],[name="search"]');
    track(eventName, {
      form_id:      form.id || '',
      form_action:  form.action || '',
      search_query: searchInput ? searchInput.value : undefined,
    });
  }, true);

  // 7. Video play detection
  document.addEventListener('play', function (e) {
    var src = e.target.src || e.target.currentSrc || '';
    track('Video Played', { video_src: src.slice(0, 200) });
  }, true);

  // ── Public API ──────────────────────────────────────────────────────────────
  global.CTTracker = {
    /**
     * Manually track a custom event.
     * Usage: CTTracker.track("Button Clicked", { label: "Hero CTA" });
     */
    track: track,

    /**
     * Immediately flush the queue.
     */
    flush: flush,

    /**
     * Override the anonymous identity with a known user ID (e.g. after login).
     * Usage: CTTracker.setIdentity("user@example.com");
     */
    setIdentity: function (id) {
      _identity = id;
      try { localStorage.setItem('ct_identity', id); } catch (_) {}
      log('Identity set to:', id);
    },

    /**
     * Returns the current identity.
     */
    getIdentity: function () { return _identity; },
  };

  log('Initialised. Account:', cfg.accountId, '| Identity:', _identity);

}(window));
